INSERT INTO models (model_id, brand_id, model_name, model_types, creator, years_active, links, description, recording_notes, artist_reference, attributes) VALUES ('4e6d9491-ede6-4b91-a696-c8975907b9b2', 'cb708484-1e2c-11f1-a0d3-0072ee78ad39', '1959 Super Lead Plexi', NULL::model_type[], NULL, '1968', 'Marshall Super Lead', 'SLP = Super Lead Plexi; JMP (Jim Marshall Products) 100W. aka Marshall JMP 100W "Legendary".  2 channels (Ch I - bright, present; Ch II - dark; full-bodied) References to Super Lead MkII land here as well.', 'Similar in design to the Super Bass, but with a big reduction in bottom end and an increase in available gain, the Super Lead is where rock rhythm guitar tones live. Lots of crunch, no flabbiness, even some saturation when pushed hard. Brash, rude, instantly recognizable sound of rock''n'' roll rebellion.', 'Pete Townshend, Jimi Hendrix, Eric Clapton, Jeff Beck, Jimmy Page, Eddie Van Halen, Angus Young (Highway to Hell, Back in Black), Yngwie Malmsteen', NULL::jsonb) ON CONFLICT (model_id) DO UPDATE SET model_types = EXCLUDED.model_types, creator = EXCLUDED.creator, years_active = EXCLUDED.years_active, description = EXCLUDED.description, recording_notes = EXCLUDED.recording_notes, artist_reference = EXCLUDED.artist_reference, attributes = EXCLUDED.attributes, updated_at = NOW();
