INSERT INTO models (model_id, brand_id, model_name, model_types, creator, years_active, links, description, recording_notes, artist_reference, attributes) VALUES ('5bf699eb-1f16-4a8b-8dd0-066881a15853', 'e502d05e-1e3c-11f1-a0d3-0072ee78ad39', '4000G Bus Compressor', '{Dynamics}'::model_type[], NULL, '1980s/90s', 'SSL 4000 Series Console', 'VCA circuit stereo / mastering / 2-bus compressor "the glue" .', 'Pop and Rock; common on mix bus or drums sub-master. Punchy + bold It was used on practically every hit record and major production from the ’80s to present days, so much that its sound has almost become a trademark. This compressor was so widely used that it later became a stand-alone rackmount unit so that it could be used separately from the large format console.', NULL, NULL::jsonb) ON CONFLICT (model_id) DO UPDATE SET model_types = EXCLUDED.model_types, creator = EXCLUDED.creator, years_active = EXCLUDED.years_active, description = EXCLUDED.description, recording_notes = EXCLUDED.recording_notes, artist_reference = EXCLUDED.artist_reference, attributes = EXCLUDED.attributes, updated_at = NOW();
