INSERT INTO models (model_id, brand_id, model_name, model_types, creator, years_active, links, description, recording_notes, artist_reference, attributes) VALUES ('6f05c91a-e835-4d31-90eb-eaf005eef38a', 'e4fd20a0-1e3c-11f1-a0d3-0072ee78ad39', '4x12 Front-Loaded (4FB)', NULL::model_type[], NULL, NULL, '4x12 Front-Loaded (4FB)', 'Closed-back, front-loaded 240W 4x12: Default Driver: Celestion Vintage 30', '"in-your-face" attack and tight, punchy, low-end performance. Known for a thick, controlled low end and a prominent upper midrange (2k-4k) that enhances attack. Frequently used fo rmodern rock and metal because it prevents "flubbing" at high volumes and offers superior, detailed and clear articulation for fast, technical playing.', NULL, NULL::jsonb) ON CONFLICT (model_id) DO UPDATE SET model_types = EXCLUDED.model_types, creator = EXCLUDED.creator, years_active = EXCLUDED.years_active, description = EXCLUDED.description, recording_notes = EXCLUDED.recording_notes, artist_reference = EXCLUDED.artist_reference, attributes = EXCLUDED.attributes, updated_at = NOW();
