INSERT INTO models (model_id, brand_id, model_name, model_types, creator, years_active, links, description, recording_notes, artist_reference, attributes) VALUES ('f3324edf-ed08-42d6-81bd-b09b91d99b86', 'e4fd20a0-1e3c-11f1-a0d3-0072ee78ad39', '4x12 Rectifier Standard Slant Cabinet', NULL::model_type[], NULL, NULL, '4x12 Rectifier Standard Slant Cabinet', 'The slopedf/slanterd 4x12 closed back. 280W. Default Driver:  4 x Celestion Vintage 30', NULL, NULL, NULL::jsonb) ON CONFLICT (model_id) DO UPDATE SET model_types = EXCLUDED.model_types, creator = EXCLUDED.creator, years_active = EXCLUDED.years_active, description = EXCLUDED.description, recording_notes = EXCLUDED.recording_notes, artist_reference = EXCLUDED.artist_reference, attributes = EXCLUDED.attributes, updated_at = NOW();
INSERT INTO models (model_id, brand_id, model_name, model_types, creator, years_active, links, description, recording_notes, artist_reference, attributes) VALUES ('8deddd4d-e24e-4536-8bf7-1912acb23026', 'e4fd20a0-1e3c-11f1-a0d3-0072ee78ad39', '4x12 Rectifier Standard Straight Cabinet', NULL::model_type[], NULL, NULL, '4x12 Rectifier Standard Straight Cabinet', 'The "oversized"/straight (OS) 4x12 closed back. 280W. Default Driver:  4 x Celestion Vintage 30', 'thundering low-end punch and resonance which is perfectly tuned with the smooth, tailored midrange and articulate, clear high-end. This is the most popular 4x12 cabinet and an icon in heavy music.', NULL, NULL::jsonb) ON CONFLICT (model_id) DO UPDATE SET model_types = EXCLUDED.model_types, creator = EXCLUDED.creator, years_active = EXCLUDED.years_active, description = EXCLUDED.description, recording_notes = EXCLUDED.recording_notes, artist_reference = EXCLUDED.artist_reference, attributes = EXCLUDED.attributes, updated_at = NOW();
INSERT INTO models (model_id, brand_id, model_name, model_types, creator, years_active, links, description, recording_notes, artist_reference, attributes) VALUES ('be9e8d19-06df-4c82-9c39-87d5ee8ebf8c', 'e4fd20a0-1e3c-11f1-a0d3-0072ee78ad39', '4x12 Rectifier Traditional Slant Cabinet', NULL::model_type[], NULL, NULL, '4x12 Rectifier Traditional Slant Cabinet', 'The Traditional 4x12 closed back. 280W. Default Driver:  4 x Celestion Vintage 30', 'Compared to Standard Recto® 4x12s, the Traditional 4x12 provides more balance between lows, mids and highs and a greater emphasis on attack. The mid-range is more pronounced and this cabinet is often preferred for styles that require tight tracking and articulate response. Straight cabinet designs also provide for a small increase of interior cabinet space, which yields slightly more bass and low-end resonance compared to Slants.', NULL, NULL::jsonb) ON CONFLICT (model_id) DO UPDATE SET model_types = EXCLUDED.model_types, creator = EXCLUDED.creator, years_active = EXCLUDED.years_active, description = EXCLUDED.description, recording_notes = EXCLUDED.recording_notes, artist_reference = EXCLUDED.artist_reference, attributes = EXCLUDED.attributes, updated_at = NOW();
