INSERT INTO models (model_id, brand_id, model_name, model_types, creator, years_active, links, description, recording_notes, artist_reference, attributes) VALUES ('320eded9-1461-471e-abbd-063193bb61a9', '65fdd29e-7434-4351-9476-41afbaa2e89d', 'Decimator', '{Dynamics,Stomp}'::model_type[], NULL, NULL, NULL, 'premier, highly responsive noise reduction system designed for electric guitars to eliminate hum and hiss, especially in high-gain rigs. "clamps noise based solely on signal passing through it"', 'widely used for its transparent, "no-stutter" performance, utilizing a single threshold knob for quick, accurate tracking of playing dynamics. Fast, transparent noise reduction that can feel abrupt if gain staging changes upstream.', NULL, NULL::jsonb) ON CONFLICT (model_id) DO UPDATE SET model_types = EXCLUDED.model_types, creator = EXCLUDED.creator, years_active = EXCLUDED.years_active, description = EXCLUDED.description, recording_notes = EXCLUDED.recording_notes, artist_reference = EXCLUDED.artist_reference, attributes = EXCLUDED.attributes, updated_at = NOW();
