INSERT INTO models (model_id, brand_id, model_name, model_types, creator, years_active, links, description, recording_notes, artist_reference, attributes) VALUES ('2a833bc8-ccbd-4153-bbf1-eb210aa8c81f', 'e503b7e4-1e3c-11f1-a0d3-0072ee78ad39', 'e609', '{Microphone}'::model_type[], NULL, NULL, 'e609', 'Dynamic super-cardioid microphone', NULL, NULL, NULL::jsonb) ON CONFLICT (model_id) DO UPDATE SET model_types = EXCLUDED.model_types, creator = EXCLUDED.creator, years_active = EXCLUDED.years_active, description = EXCLUDED.description, recording_notes = EXCLUDED.recording_notes, artist_reference = EXCLUDED.artist_reference, attributes = EXCLUDED.attributes, updated_at = NOW();
INSERT INTO models (model_id, brand_id, model_name, model_types, creator, years_active, links, description, recording_notes, artist_reference, attributes) VALUES ('a37830ff-b507-408a-b218-1887bbf41e05', 'ae17e6e7-e6a2-4aad-a25a-e574be9f1c8e', 'E610 Savage 120', NULL::model_type[], 'Horst Langer', 'Late 1990s', NULL, '120W · 2 channels (Clean / Lead) with multiple gain modes · 41 ECC 83, 2 x 6550 tubes. · solid-state rectifier · shared 3-band EQ (Bass / Mid / Treble) · Presence · Master Volume · serial/parallel effects loop · no MIDI (simpler signal path than Invader/Powerball)', 'Aggressive, raw, and less compressed than other ENGL high-gain amps; strong midrange bite with fast attack; feels more “Marshall-on-steroids” than polished modern metal; favored for thrash, hard rock, and players wanting ENGL tightness without heavy saturation', NULL, NULL::jsonb) ON CONFLICT (model_id) DO UPDATE SET model_types = EXCLUDED.model_types, creator = EXCLUDED.creator, years_active = EXCLUDED.years_active, description = EXCLUDED.description, recording_notes = EXCLUDED.recording_notes, artist_reference = EXCLUDED.artist_reference, attributes = EXCLUDED.attributes, updated_at = NOW();
INSERT INTO models (model_id, brand_id, model_name, model_types, creator, years_active, links, description, recording_notes, artist_reference, attributes) VALUES ('a03cfd4d-baa9-4e6f-ba40-a270b16bfc5f', 'ae17e6e7-e6a2-4aad-a25a-e574be9f1c8e', 'E635 Fireball 100', NULL::model_type[], 'Horst Langer', 'Early-mid 2000s', 'Fireball 100 E635', '100W · 2 channels (Clean / Lead) · 4× EL34 power tubes (some regions shipped 6L6 variants) · solid-state rectifier · shared 3-band EQ (Bass / Mid / Treble) · Presence · Master Volume · Depth Boost · built-in Noise Gate (lead channel) · serial effects loop · MIDI optional via external switcher', 'Extremely tight, aggressive modern high-gain; fast attack with strong low-end control; less saturated than Powerball but more focused; excels at palm-muted metal, drop tunings, and rhythm tracking; commonly associated with modern metal and metalcore production (used by bands in the In Flames / Killswitch Engage / early 2000s European metal orbit). Focused, brutal rhythm machine. Not a vintage or lead centric ENGL', NULL, NULL::jsonb) ON CONFLICT (model_id) DO UPDATE SET model_types = EXCLUDED.model_types, creator = EXCLUDED.creator, years_active = EXCLUDED.years_active, description = EXCLUDED.description, recording_notes = EXCLUDED.recording_notes, artist_reference = EXCLUDED.artist_reference, attributes = EXCLUDED.attributes, updated_at = NOW();
INSERT INTO models (model_id, brand_id, model_name, model_types, creator, years_active, links, description, recording_notes, artist_reference, attributes) VALUES ('ffc73509-7b20-43d4-a4e6-63d757244db3', 'ae17e6e7-e6a2-4aad-a25a-e574be9f1c8e', 'E642 Invader 100', NULL::model_type[], 'Horst Langer', 'Early 2000s (≈2003)', NULL, '100W · 4 channels (Clean / Crunch / Lead I / Lead II) · 4× EL34 power tubes (factory; 6L6 compatible) · solid-state rectifier · 2 independent 3-band EQs (one for Clean/Crunch, one for Lead I/II) · Presence · Depth Punch · dual Master Volumes · built-in Noise Gate · serial/parallel effects loop · full MIDI control', 'Extremely tight, modern high-gain with surgical low end; aggressive but controlled saturation; excels at layered rhythm tracking and precise leads; widely used in modern metal and hard rock production (associated with bands in the European metal / metalcore scene)', NULL, NULL::jsonb) ON CONFLICT (model_id) DO UPDATE SET model_types = EXCLUDED.model_types, creator = EXCLUDED.creator, years_active = EXCLUDED.years_active, description = EXCLUDED.description, recording_notes = EXCLUDED.recording_notes, artist_reference = EXCLUDED.artist_reference, attributes = EXCLUDED.attributes, updated_at = NOW();
INSERT INTO models (model_id, brand_id, model_name, model_types, creator, years_active, links, description, recording_notes, artist_reference, attributes) VALUES ('53345c34-d5ea-4319-9e5f-e3200a7b0170', 'ae17e6e7-e6a2-4aad-a25a-e574be9f1c8e', 'E643 Invader 150', NULL::model_type[], 'Horst Langer', 'Early–mid 2000s', NULL, '150W · 4 channels (Clean / Crunch / Lead I / Lead II) · 6× EL34 power tubes · solid-state rectifier · 2 independent 3-band EQs · Presence · Depth Punch · dual Master Volumes · built-in Noise Gate · serial/parallel effects loop · full MIDI control · higher plate voltage and larger transformers than the 100', 'Same voicing as the Invader 100 but with more headroom, punch, and authority; stays tighter at extreme volumes; favored for large stages and ultra-tight modern metal tones; less compression than the 100W version', NULL, NULL::jsonb) ON CONFLICT (model_id) DO UPDATE SET model_types = EXCLUDED.model_types, creator = EXCLUDED.creator, years_active = EXCLUDED.years_active, description = EXCLUDED.description, recording_notes = EXCLUDED.recording_notes, artist_reference = EXCLUDED.artist_reference, attributes = EXCLUDED.attributes, updated_at = NOW();
INSERT INTO models (model_id, brand_id, model_name, model_types, creator, years_active, links, description, recording_notes, artist_reference, attributes) VALUES ('5dba056e-3007-4294-9c5d-fa76d1c248a2', 'ae17e6e7-e6a2-4aad-a25a-e574be9f1c8e', 'E645 Powerball', NULL::model_type[], 'Horst Langer', 'Early 2000s (≈2001–2002)', NULL, '100W · 4 channels (Clean / Crunch / Lead I / Lead II) · 4× EL34 power tubes (6L6 compatible) · solid-state rectifier · shared 3-band EQ (Bass / Mid / Treble) · Presence · Depth Boost · dual Master Volumes · built-in Noise Gate · serial/parallel effects loop · full MIDI control', 'Extremely saturated, compressed modern high-gain with massive low end; smooth top end and strong noise suppression; excels at heavy rhythm tracking, drop tunings, and dense mixes; became a defining amp of early-2000s European metal and metalcore production', NULL, NULL::jsonb) ON CONFLICT (model_id) DO UPDATE SET model_types = EXCLUDED.model_types, creator = EXCLUDED.creator, years_active = EXCLUDED.years_active, description = EXCLUDED.description, recording_notes = EXCLUDED.recording_notes, artist_reference = EXCLUDED.artist_reference, attributes = EXCLUDED.attributes, updated_at = NOW();
INSERT INTO models (model_id, brand_id, model_name, model_types, creator, years_active, links, description, recording_notes, artist_reference, attributes) VALUES ('4bdf7896-734f-41d0-98ab-c06917927385', 'ae17e6e7-e6a2-4aad-a25a-e574be9f1c8e', 'E645II Powerball II', NULL::model_type[], 'Horst Langer', 'Early 2010s (≈2011)', 'E645II Powerball II', '100W · 4 channels (Clean / Crunch / Lead I / Lead II) · 4× EL34 power tubes (6L6 compatible) · solid-state rectifier · 2 independent 3-band EQs (Clean/Crunch and Lead I/II) · Presence · Depth Punch · dual Master Volumes · enhanced built-in Noise Gate · serial/parallel effects loop · full MIDI control · revised power supply and tighter low-end response vs original', 'Retains the Powerball’s signature saturation but with tighter bass, clearer mids, and better note separation; less blanket compression than the original; more flexible for studio work and layered guitars while still firmly modern-metal focused; preferred in later-era metal and precision rhythm tracking', NULL, NULL::jsonb) ON CONFLICT (model_id) DO UPDATE SET model_types = EXCLUDED.model_types, creator = EXCLUDED.creator, years_active = EXCLUDED.years_active, description = EXCLUDED.description, recording_notes = EXCLUDED.recording_notes, artist_reference = EXCLUDED.artist_reference, attributes = EXCLUDED.attributes, updated_at = NOW();
INSERT INTO models (model_id, brand_id, model_name, model_types, creator, years_active, links, description, recording_notes, artist_reference, attributes) VALUES ('e09875dc-f2bf-4032-8541-eb9123a77b00', 'ae17e6e7-e6a2-4aad-a25a-e574be9f1c8e', 'E646 Victor Smolski Ltd.', NULL::model_type[], 'Horst Langer; Victor Smolski', NULL, 'E646 Victor Smolski Ltd', '100W · 4 channels (Clean / Crunch / Lead I / Lead II) · 4× EL34 power tubes · solid-state rectifier · 2 independent 3-band EQs (Clean/Crunch and Lead I/II) · Presence · Depth Boost · dual Master Volumes · built-in Noise Gate · serial/parallel effects loop · full MIDI control', 'fast attack, punchy rhythm, furious leads, sparking clean sounds. Very tight, articulate modern high-gain with strong mid focus and controlled low end; less compressed than Powerball, more aggressive upper mids; excels at fast, precise metal riffing and technical leads; closely associated with Victor Smolski (Rage) and European power/prog metal', NULL, NULL::jsonb) ON CONFLICT (model_id) DO UPDATE SET model_types = EXCLUDED.model_types, creator = EXCLUDED.creator, years_active = EXCLUDED.years_active, description = EXCLUDED.description, recording_notes = EXCLUDED.recording_notes, artist_reference = EXCLUDED.artist_reference, attributes = EXCLUDED.attributes, updated_at = NOW();
INSERT INTO models (model_id, brand_id, model_name, model_types, creator, years_active, links, description, recording_notes, artist_reference, attributes) VALUES ('4d7adc92-d38d-4369-90d2-bc149ecf11fa', 'ae17e6e7-e6a2-4aad-a25a-e574be9f1c8e', 'E650 (Ritchie Blackmore Signature)', NULL::model_type[], 'Horst Langer; Ritchie Blackmore', 'Mid–late 1990s', 'E650 (Ritchie Blackmore Signature)', '100W · 2 channels (Clean / Lead) · 4× 6L6GC power tubes · solid-state rectifier · shared 3-band EQ (Bass / Mid / Treble) · Presence · Master Volume · serial effects loop · no built-in reverb', 'Very tight, articulate, mid-forward distortion; fast attack with minimal sag; cleaner and more controlled than typical ENGL high-gain amps; excels at classical rock, neo-classical, and precise lead work; associated with Ritchie Blackmore (Deep Purple / Rainbow–era tones in later years', NULL, NULL::jsonb) ON CONFLICT (model_id) DO UPDATE SET model_types = EXCLUDED.model_types, creator = EXCLUDED.creator, years_active = EXCLUDED.years_active, description = EXCLUDED.description, recording_notes = EXCLUDED.recording_notes, artist_reference = EXCLUDED.artist_reference, attributes = EXCLUDED.attributes, updated_at = NOW();
