INSERT INTO models (model_id, brand_id, model_name, model_types, creator, years_active, links, description, recording_notes, artist_reference, attributes) VALUES ('74912e48-180b-43f8-bd39-3ec8b14561b1', '111482d4-8033-40a9-bf4c-d6f70f870df9', 'EB-0', '{Bass}'::model_type[], NULL, NULL, 'Gibson EB-0', NULL, NULL, NULL, NULL::jsonb) ON CONFLICT (model_id) DO UPDATE SET model_types = EXCLUDED.model_types, creator = EXCLUDED.creator, years_active = EXCLUDED.years_active, description = EXCLUDED.description, recording_notes = EXCLUDED.recording_notes, artist_reference = EXCLUDED.artist_reference, attributes = EXCLUDED.attributes, updated_at = NOW();
INSERT INTO models (model_id, brand_id, model_name, model_types, creator, years_active, links, description, recording_notes, artist_reference, attributes) VALUES ('f8c022b7-e3ff-40f2-93dd-4889a123926b', 'cb6fd052-1e2c-11f1-a0d3-0072ee78ad39', 'Echoplex EP-1', '{Delay}'::model_type[], 'Mike Battle', 'early 1960s', 'Echoplex', 'Mike Battles pioneering tube-driven tape delay unit. "O.G" Tape Delay. First delay unit to feature a sliding record head for adjustable delay times.', 'warm, organic and satured echo sounds. Famous for the (first?) slapback echo and along, trailing, ambient delays. Soft, dark, compressed repeats with pitch wander and bloom.', NULL, NULL::jsonb) ON CONFLICT (model_id) DO UPDATE SET model_types = EXCLUDED.model_types, creator = EXCLUDED.creator, years_active = EXCLUDED.years_active, description = EXCLUDED.description, recording_notes = EXCLUDED.recording_notes, artist_reference = EXCLUDED.artist_reference, attributes = EXCLUDED.attributes, updated_at = NOW();
INSERT INTO models (model_id, brand_id, model_name, model_types, creator, years_active, links, description, recording_notes, artist_reference, attributes) VALUES ('cb5c24ee-d657-41e2-a49e-3af4e41451cd', 'cb6fd052-1e2c-11f1-a0d3-0072ee78ad39', 'Echoplex EP-3', '{Delay}'::model_type[], 'Mike Battle, Don Dixon', '1970', 'Echoplex', 'classic 1/4" tape echo/delay.', 'EP-3 was heavily used by guitarists. EP-4 not so much due to the noise reduction circuit. Clearer, brighter repeats (from the EP-1) with a focused mid push and tighter modulation.', NULL, NULL::jsonb) ON CONFLICT (model_id) DO UPDATE SET model_types = EXCLUDED.model_types, creator = EXCLUDED.creator, years_active = EXCLUDED.years_active, description = EXCLUDED.description, recording_notes = EXCLUDED.recording_notes, artist_reference = EXCLUDED.artist_reference, attributes = EXCLUDED.attributes, updated_at = NOW();
INSERT INTO models (model_id, brand_id, model_name, model_types, creator, years_active, links, description, recording_notes, artist_reference, attributes) VALUES ('b2c7ce17-d8be-45c2-a690-05d5d6d099c3', 'cb6fd052-1e2c-11f1-a0d3-0072ee78ad39', 'Echoplex EP-4', '{Delay}'::model_type[], 'Mike Battle, Don Dixon', '1970', 'Echoplex', 'classic 1/4" tape echo/delay.', 'EP-3 was heavily used by guitarists. EP-4 not so much due to the noise reduction circuit. Clearer, brighter repeats (from the EP-1) with a focused mid push and tighter modulation.', NULL, NULL::jsonb) ON CONFLICT (model_id) DO UPDATE SET model_types = EXCLUDED.model_types, creator = EXCLUDED.creator, years_active = EXCLUDED.years_active, description = EXCLUDED.description, recording_notes = EXCLUDED.recording_notes, artist_reference = EXCLUDED.artist_reference, attributes = EXCLUDED.attributes, updated_at = NOW();
INSERT INTO models (model_id, brand_id, model_name, model_types, creator, years_active, links, description, recording_notes, artist_reference, attributes) VALUES ('623b3a05-0ea1-4aee-b2da-c16ebb598416', 'cb67b5ca-1e2c-11f1-a0d3-0072ee78ad39', 'Echorec 2 T7E', '{Delay}'::model_type[], NULL, '1950s-70s', 'Binson Echorec', 'legendary Italian magnetic drum delay unit. Unlike tape delays, it uses a rotating magnetic drum,', 'renowned for its warm, rhythmic echoes.  Drum providing a unique, lo-fi, and swirling sound', 'Pink Floyd (David Gilmour), Beatles', NULL::jsonb) ON CONFLICT (model_id) DO UPDATE SET model_types = EXCLUDED.model_types, creator = EXCLUDED.creator, years_active = EXCLUDED.years_active, description = EXCLUDED.description, recording_notes = EXCLUDED.recording_notes, artist_reference = EXCLUDED.artist_reference, attributes = EXCLUDED.attributes, updated_at = NOW();
