INSERT INTO models (model_id, brand_id, model_name, model_types, creator, years_active, links, description, recording_notes, artist_reference, attributes) VALUES ('84c702e8-bc39-4e32-9278-ffa3f4c676e7', 'e5063be0-1e3c-11f1-a0d3-0072ee78ad39', 'Ecoplate III', '{Reverb}'::model_type[], 'Jim Cunningham', '1980s', 'Studio Technologies Echoplate III', 'Stainless steel plate reverb w/ adjustable delay times.', 'Michael Jackson, Quincy Jones. Wide, bright and consistent sound [vocals, drums] Brighter, cleaner, more compact alternative to EMT', NULL, NULL::jsonb) ON CONFLICT (model_id) DO UPDATE SET model_types = EXCLUDED.model_types, creator = EXCLUDED.creator, years_active = EXCLUDED.years_active, description = EXCLUDED.description, recording_notes = EXCLUDED.recording_notes, artist_reference = EXCLUDED.artist_reference, attributes = EXCLUDED.attributes, updated_at = NOW();
INSERT INTO models (model_id, brand_id, model_name, model_types, creator, years_active, links, description, recording_notes, artist_reference, attributes) VALUES ('9f0b65c2-8cf2-46aa-89d4-af6ac7a3f09b', 'cb683482-1e2c-11f1-a0d3-0072ee78ad39', 'Ecstasy 101B', NULL::model_type[], NULL, NULL, 'Bogner Amps', 'flagship 100W head. EL34 tubes. 3 ch (Clean, Blue, Red)', 'The Blue channel is known for lower-to-mid gain, "woody" overdrive, while the Red channel offers thick, high-gain distortion suitable for modern rock and metal. staple for professional guitarists needing to cover a vast spectrum of gain with a single, reliable amplifier, particularly in studio environments; Joe Satriani', NULL, NULL::jsonb) ON CONFLICT (model_id) DO UPDATE SET model_types = EXCLUDED.model_types, creator = EXCLUDED.creator, years_active = EXCLUDED.years_active, description = EXCLUDED.description, recording_notes = EXCLUDED.recording_notes, artist_reference = EXCLUDED.artist_reference, attributes = EXCLUDED.attributes, updated_at = NOW();
INSERT INTO models (model_id, brand_id, model_name, model_types, creator, years_active, links, description, recording_notes, artist_reference, attributes) VALUES ('c3797723-34ec-4684-90e6-3fe7c88a4305', 'cb683482-1e2c-11f1-a0d3-0072ee78ad39', 'Ecstasy 3534', NULL::model_type[], NULL, NULL, 'Bogner Amps', '35W version of 101B. EL34 tubes. 3 ch (Clean, Blue, Red)', 'The Blue channel is known for lower-to-mid gain, "woody" overdrive, while the Red channel offers thick, high-gain distortion suitable for modern rock and metal. staple for professional guitarists needing to cover a vast spectrum of gain with a single, reliable amplifier, particularly in studio environments', NULL, NULL::jsonb) ON CONFLICT (model_id) DO UPDATE SET model_types = EXCLUDED.model_types, creator = EXCLUDED.creator, years_active = EXCLUDED.years_active, description = EXCLUDED.description, recording_notes = EXCLUDED.recording_notes, artist_reference = EXCLUDED.artist_reference, attributes = EXCLUDED.attributes, updated_at = NOW();
