INSERT INTO models (model_id, brand_id, model_name, model_types, creator, years_active, links, description, recording_notes, artist_reference, attributes) VALUES ('c85e3abf-14a7-4383-a119-c6242b2a9e0a', 'e4ff88f4-1e3c-11f1-a0d3-0072ee78ad39', 'Eight Voice', '{Synth,Sampler}'::model_type[], 'Tom Oberheim', '1977-80', 'Eight Voice', 'Polyphonic. 8 classic Oberheim SEM modules stacked together alongside a Polyphonic Synth Programmer. 16 VCOs.', 'fat, thick, organic majestic', 'Herbie Hancock, Styx, Rush', NULL::jsonb) ON CONFLICT (model_id) DO UPDATE SET model_types = EXCLUDED.model_types, creator = EXCLUDED.creator, years_active = EXCLUDED.years_active, description = EXCLUDED.description, recording_notes = EXCLUDED.recording_notes, artist_reference = EXCLUDED.artist_reference, attributes = EXCLUDED.attributes, updated_at = NOW();
