INSERT INTO models (model_id, brand_id, model_name, model_types, creator, years_active, links, description, recording_notes, artist_reference, attributes) VALUES ('30cc03a5-fbd8-4504-bab9-76c79120a9a9', 'f7719248-1e3c-11f1-a0d3-0072ee78ad39', 'ELA M 251', '{Microphone}'::model_type[], NULL, NULL, 'ELA M 251', 'Multi-Pattern Large Tube Condenser Microphone. Designed + Made by AKG w/ hard-wared Telefunken AC701k tube.', '(airy, open) vocals, acoustic instruments. Slightly warmer and more low end-extension than 251E.', 'Beyonce, Bruce Springsteen, Tom Petty', NULL::jsonb) ON CONFLICT (model_id) DO UPDATE SET model_types = EXCLUDED.model_types, creator = EXCLUDED.creator, years_active = EXCLUDED.years_active, description = EXCLUDED.description, recording_notes = EXCLUDED.recording_notes, artist_reference = EXCLUDED.artist_reference, attributes = EXCLUDED.attributes, updated_at = NOW();
INSERT INTO models (model_id, brand_id, model_name, model_types, creator, years_active, links, description, recording_notes, artist_reference, attributes) VALUES ('ebc9235b-f4ed-4c62-a491-3586c4bc721d', 'f7719248-1e3c-11f1-a0d3-0072ee78ad39', 'ELA M 251E', '{Microphone}'::model_type[], NULL, '1959 - 62', 'ELA M 251E', 'Multi-Pattern Large Tube Condenser Microphone. Designed + Made by AKG. E = "Export" version, uses a socketed 6072 tube w/ fully brass capsule that was more readily available outside of Europe . One of the rarest and most highly regarded mics of all time. Similar to C12 (AKG)', 'A-List artist vocal mic.  [Vocals, piano, drum OH]', 'Beyonce, Joni Mitchell, Celine Dion', NULL::jsonb) ON CONFLICT (model_id) DO UPDATE SET model_types = EXCLUDED.model_types, creator = EXCLUDED.creator, years_active = EXCLUDED.years_active, description = EXCLUDED.description, recording_notes = EXCLUDED.recording_notes, artist_reference = EXCLUDED.artist_reference, attributes = EXCLUDED.attributes, updated_at = NOW();
INSERT INTO models (model_id, brand_id, model_name, model_types, creator, years_active, links, description, recording_notes, artist_reference, attributes) VALUES ('66581617-75ff-40ea-965c-cb97cb4374fd', 'c5823d1f-a4a9-4dd4-a122-fa0cae45b12f', 'ElecTribe R (ER-1)', '{Synth,Sampler}'::model_type[], NULL, '1990s', 'ElecTribe R', 'synth + sequencer', NULL, 'Orbital, Cirrus, Dan Hekate, Saulaterre, The Prodigy, YB70, 69db, MDFMK, Crystal Distortion, the Crystal Method, Massive Attack, and the Chemical Brothers.', NULL::jsonb) ON CONFLICT (model_id) DO UPDATE SET model_types = EXCLUDED.model_types, creator = EXCLUDED.creator, years_active = EXCLUDED.years_active, description = EXCLUDED.description, recording_notes = EXCLUDED.recording_notes, artist_reference = EXCLUDED.artist_reference, attributes = EXCLUDED.attributes, updated_at = NOW();
INSERT INTO models (model_id, brand_id, model_name, model_types, creator, years_active, links, description, recording_notes, artist_reference, attributes) VALUES ('a36173ab-55dc-4d6f-ac55-f280f2078a30', 'cb6ef06a-1e2c-11f1-a0d3-0072ee78ad39', 'Electric Mistress', '{Modulation,Stomp}'::model_type[], NULL, NULL, NULL, 'Core flanger with a fixed, classic voicing', 'thinner, glassier sweep. More metallic / jet-like than Deluxe. Very late-’70s / new-wave / Andy Summers vibe. Bright, airy, shimmery, swirling. lives in the upper mids and stays subtle. While it has amazing warmth, it is also capable of very versatile chorus and ring modulation type sounds.', NULL, NULL::jsonb) ON CONFLICT (model_id) DO UPDATE SET model_types = EXCLUDED.model_types, creator = EXCLUDED.creator, years_active = EXCLUDED.years_active, description = EXCLUDED.description, recording_notes = EXCLUDED.recording_notes, artist_reference = EXCLUDED.artist_reference, attributes = EXCLUDED.attributes, updated_at = NOW();
