INSERT INTO models (model_id, brand_id, model_name, model_types, creator, years_active, links, description, recording_notes, artist_reference, attributes) VALUES ('d1bf629c-1817-4291-8069-0fc75e01da7e', '55bb06af-53e7-48d8-871e-3bc63c134f37', 'EQ', '{EQ}'::model_type[], NULL, '1960s', NULL, 'Custom-built inductor based graphic EQ used in the Motown Detroit studio. 7 bands of fixed-frequency (50, 130, 320, 800, 2k 12.5k), w/ proportional Q (narrower at higher boost/cut levels). UTC (United Tech. Corp.) and Freed transformers for warmth and harmanoic saturation. Specialized mastering version has a 1/2-speed option and mid-side functionality for stereo image control.', 'secret sauce of Motown sound.', NULL, NULL::jsonb) ON CONFLICT (model_id) DO UPDATE SET model_types = EXCLUDED.model_types, creator = EXCLUDED.creator, years_active = EXCLUDED.years_active, description = EXCLUDED.description, recording_notes = EXCLUDED.recording_notes, artist_reference = EXCLUDED.artist_reference, attributes = EXCLUDED.attributes, updated_at = NOW();
