INSERT INTO models (model_id, brand_id, model_name, model_types, creator, years_active, links, description, recording_notes, artist_reference, attributes) VALUES ('6b3c3e03-f2c2-4a87-bc5c-0832a58b50d2', 'cb6ed83c-1e2c-11f1-a0d3-0072ee78ad39', 'Filter Factory', '{Modulation}'::model_type[], NULL, NULL, NULL, 'classic hardware audio processor, a 2U rack unit featuring an analog stereo/mono filter (Low, High, Band Pass, Notch) with real-time controls, built-in distortion ("Buzz"), LFO modulation, tap tempo, and MIDI,', 'used by electronic musicians and DJs for filtering synths, drums, vocals, or entire mixes. It offers deep sound shaping with analog character and digital control, allowing for dynamic sweeps, rhythmic effects via momentary buttons, and studio automation', NULL, NULL::jsonb) ON CONFLICT (model_id) DO UPDATE SET model_types = EXCLUDED.model_types, creator = EXCLUDED.creator, years_active = EXCLUDED.years_active, description = EXCLUDED.description, recording_notes = EXCLUDED.recording_notes, artist_reference = EXCLUDED.artist_reference, attributes = EXCLUDED.attributes, updated_at = NOW();
