INSERT INTO models (model_id, brand_id, model_name, model_types, creator, years_active, links, description, recording_notes, artist_reference, attributes) VALUES ('945bf7b8-9942-4699-8e54-d49f3542039a', 'cb6f8cfa-1e2c-11f1-a0d3-0072ee78ad39', 'Flanger', '{Modulation,Stomp}'::model_type[], NULL, NULL, 'MXR Flanger (Modern Reissue)', 'classic, 4-knob analog BBD pedal  to. It features manual, width, speed, and regeneration controls,', 'deliver thick modulation, ranging from subtle chorus and vibrato to intense "jet plane" sweeps and metallic, sci-fi sounds. warm, deep, and dramatic tone', 'Eddie Van Halen', NULL::jsonb) ON CONFLICT (model_id) DO UPDATE SET model_types = EXCLUDED.model_types, creator = EXCLUDED.creator, years_active = EXCLUDED.years_active, description = EXCLUDED.description, recording_notes = EXCLUDED.recording_notes, artist_reference = EXCLUDED.artist_reference, attributes = EXCLUDED.attributes, updated_at = NOW();
