INSERT INTO models (model_id, brand_id, model_name, model_types, creator, years_active, links, description, recording_notes, artist_reference, attributes) VALUES ('90ed4e72-dccb-4fef-ad6b-32a71201b996', '05bf6ddc-beab-41d9-b70f-bc2108713569', 'Foot Phaser', '{Modulation,Stomp}'::model_type[], NULL, '1970s', NULL, 'analog phaser built into a wah-style treadle enclosure. It is known for using 10 matched JFET transistors, offering both auto-modulation and manual expression control, with speed, depth, and intensity controls.', 'lush, deep phaser effect', 'Brian May', NULL::jsonb) ON CONFLICT (model_id) DO UPDATE SET model_types = EXCLUDED.model_types, creator = EXCLUDED.creator, years_active = EXCLUDED.years_active, description = EXCLUDED.description, recording_notes = EXCLUDED.recording_notes, artist_reference = EXCLUDED.artist_reference, attributes = EXCLUDED.attributes, updated_at = NOW();
