INSERT INTO models (model_id, brand_id, model_name, model_types, creator, years_active, links, description, recording_notes, artist_reference, attributes) VALUES ('a2d977e8-093e-4bff-a9b9-1022fd45dff4', 'f77543c0-1e3c-11f1-a0d3-0072ee78ad39', 'Fuzz Factory', '{Harmonic Coloration,Stomp}'::model_type[], NULL, NULL, 'Fuzz Factory', NULL, 'This model alters the sound of the input signal by changing the sample-rate, cutoff frequency and by distorting it. This effect can produce very aggressive distorted sounds, more pronounced than overdrive stompboxes. The Low pass filter is very creative when combined to high distortion levels.', NULL, NULL::jsonb) ON CONFLICT (model_id) DO UPDATE SET model_types = EXCLUDED.model_types, creator = EXCLUDED.creator, years_active = EXCLUDED.years_active, description = EXCLUDED.description, recording_notes = EXCLUDED.recording_notes, artist_reference = EXCLUDED.artist_reference, attributes = EXCLUDED.attributes, updated_at = NOW();
