INSERT INTO models (model_id, brand_id, model_name, model_types, creator, years_active, links, description, recording_notes, artist_reference, attributes) VALUES ('367bbd82-dc02-4aac-a4af-6606a43a5926', 'e4fe502e-1e3c-11f1-a0d3-0072ee78ad39', 'Fuzzrite', '{Stomp}'::model_type[], NULL, '1960s', NULL, 'American-made two transistor fuzz pedal. Usually silicon (rarer/earlier versions made of Germanium)', 'known for its distinctively raspy, aggressive and "bitten" tone, often characterized by a pronounced midrange. Unique depth knob acts as a blend for a signature octave-like, snarling and sometimes "torn speaker" sound.', 'Iron Butterfly, Jimi Hendrix', NULL::jsonb) ON CONFLICT (model_id) DO UPDATE SET model_types = EXCLUDED.model_types, creator = EXCLUDED.creator, years_active = EXCLUDED.years_active, description = EXCLUDED.description, recording_notes = EXCLUDED.recording_notes, artist_reference = EXCLUDED.artist_reference, attributes = EXCLUDED.attributes, updated_at = NOW();
