INSERT INTO models (model_id, brand_id, model_name, model_types, creator, years_active, links, description, recording_notes, artist_reference, attributes) VALUES ('6b94d5a6-2030-4cc6-8c53-8e20d661c30f', 'e4fe93a4-1e3c-11f1-a0d3-0072ee78ad39', 'KM54', '{Microphone}'::model_type[], NULL, '1953', 'KM54', 'rare; featuring thin nickel (medium) diaphgram w/ excellent transient response. pressure gradient cardioid condenser counterpart to the omnidirectional small diaphragm microphone KM 53. uses Telefunken AC701 subminiature triode. Same nickel capsule as M50, but different sound due to body configuration. Extremely thin nickel diaphragm. Excellent transient repsonse, but fragile.  max on-axis sensitivty', '[acoustic guitar, strings, drum OH]', 'Larry Carlton, Ry Cooder, Yo You Ma, Joe Pass, Kenny Burrell, Eric Clapton', NULL::jsonb) ON CONFLICT (model_id) DO UPDATE SET model_types = EXCLUDED.model_types, creator = EXCLUDED.creator, years_active = EXCLUDED.years_active, description = EXCLUDED.description, recording_notes = EXCLUDED.recording_notes, artist_reference = EXCLUDED.artist_reference, attributes = EXCLUDED.attributes, updated_at = NOW();
