INSERT INTO models (model_id, brand_id, model_name, model_types, creator, years_active, links, description, recording_notes, artist_reference, attributes) VALUES ('f2e9979d-11c8-44f0-a022-6565710e7d9c', 'e4fe93a4-1e3c-11f1-a0d3-0072ee78ad39', 'M49b', '{Microphone}'::model_type[], NULL, '1960s', 'M49', 'first studio microphone with a continuously variable directional pattern. It used the same large diaphragm capsule as the U 47. Uses K47 capsule, but is smoother / less coloered than U47 due to transparent headbasket. Uses Telefunken AC701 Tube', 'Smoother, less coloered.', 'Neil Diamond, Barbara Streisand, Phil Collins, Winona Judd, Bobby McFerrin, Joni Mitchell', NULL::jsonb) ON CONFLICT (model_id) DO UPDATE SET model_types = EXCLUDED.model_types, creator = EXCLUDED.creator, years_active = EXCLUDED.years_active, description = EXCLUDED.description, recording_notes = EXCLUDED.recording_notes, artist_reference = EXCLUDED.artist_reference, attributes = EXCLUDED.attributes, updated_at = NOW();
INSERT INTO models (model_id, brand_id, model_name, model_types, creator, years_active, links, description, recording_notes, artist_reference, attributes) VALUES ('0c7cc262-3f4e-4175-a798-25d20deda508', 'e4fe93a4-1e3c-11f1-a0d3-0072ee78ad39', 'M50', '{Microphone}'::model_type[], NULL, NULL, 'M50', 'capsule mounted on a plexiglass sphere (high freq rise and ooff-axis response that becomes more directional at higher freq). Same body  / headbasket and tube of M49 - but sounds completely different. Noted for its far distance placement consistency, the response of becomes more cardioid above 800 Hz. medium diaphragm omni', NULL, 'ET, Superman, 1941, Jaws II, Star Trek, Taxi Driver etc.', NULL::jsonb) ON CONFLICT (model_id) DO UPDATE SET model_types = EXCLUDED.model_types, creator = EXCLUDED.creator, years_active = EXCLUDED.years_active, description = EXCLUDED.description, recording_notes = EXCLUDED.recording_notes, artist_reference = EXCLUDED.artist_reference, attributes = EXCLUDED.attributes, updated_at = NOW();
