INSERT INTO models (model_id, brand_id, model_name, model_types, creator, years_active, links, description, recording_notes, artist_reference, attributes) VALUES ('939bd7d5-5a2b-475a-9987-20b209e952bb', '147af267-3b4d-43c8-a091-a66c906304dc', 'OCD', '{Harmonic Coloration,Stomp}'::model_type[], NULL, NULL, 'OCDv2', 'OCD (Obsessive Compulsive Drive) highly popular, touch-sensitive guitar overdrive pedal , featuring simple Volume, Drive, Tone controls, and an HP/LP (High Peak/Low Peak) switch for voicing versatility. It uses MOSFETs for clipping, offers great clarity, and comes in various versions (V1, V2, GE) with enhancements like buffered bypass. DEFAULT is to model V1 unless specified by the plugin / model.', 'known for its dynamic, amp-like sound, reacting to picking dynamics and guitar volume for expressive tones from light grit to heavier distortion. blues, rock,', NULL, NULL::jsonb) ON CONFLICT (model_id) DO UPDATE SET model_types = EXCLUDED.model_types, creator = EXCLUDED.creator, years_active = EXCLUDED.years_active, description = EXCLUDED.description, recording_notes = EXCLUDED.recording_notes, artist_reference = EXCLUDED.artist_reference, attributes = EXCLUDED.attributes, updated_at = NOW();
