INSERT INTO models (model_id, brand_id, model_name, model_types, creator, years_active, links, description, recording_notes, artist_reference, attributes) VALUES ('9fb44bc9-91fe-40ec-8711-18f9be35b503', '147af267-3b4d-43c8-a091-a66c906304dc', 'Plimsoul', '{Harmonic Coloration,Stomp}'::model_type[], NULL, NULL, NULL, 'versatile, hand-wired, two-stage overdrive/distortion pedal featuring both soft-clipping and hard-diode clipping, designed to emulate British tube amp distortion. Key specs include a 4-knob layout (Level, Hi-Cut, Sustain, Stage 2), ~500K Ohm input impedance, 300 Ohm output impedance, and operation between 9-18V DC, allowing for increased headroom', 'known for its ability to go from soft, bluesy overdrive to harder, more aggressive distortion, offering high touch sensitivity', NULL, NULL::jsonb) ON CONFLICT (model_id) DO UPDATE SET model_types = EXCLUDED.model_types, creator = EXCLUDED.creator, years_active = EXCLUDED.years_active, description = EXCLUDED.description, recording_notes = EXCLUDED.recording_notes, artist_reference = EXCLUDED.artist_reference, attributes = EXCLUDED.attributes, updated_at = NOW();
