INSERT INTO models (model_id, brand_id, model_name, model_types, creator, years_active, links, description, recording_notes, artist_reference, attributes) VALUES ('b0df2e5e-53a7-414e-b299-55852ae5283f', 'cb6ef06a-1e2c-11f1-a0d3-0072ee78ad39', 'Ram''s Head Big Muff Pi', '{Harmonic Coloration,Stomp,Dynamics}'::model_type[], NULL, NULL, 'Ram''s Head Big Muff Pi', 'Faithful reproduction of the highly coveted 1973 Violet Ram’s Head Big Muff Pi heard on countless classic recordings and famous guitar solos!', 'Smooth and lyrical. Smoother and darker than the Triangle, with singing sustain, slightly scooped mids, and a refined, liquid lead voice. Creamy, violin-like sustain that blooms and stays musical under long notes.', NULL, NULL::jsonb) ON CONFLICT (model_id) DO UPDATE SET model_types = EXCLUDED.model_types, creator = EXCLUDED.creator, years_active = EXCLUDED.years_active, description = EXCLUDED.description, recording_notes = EXCLUDED.recording_notes, artist_reference = EXCLUDED.artist_reference, attributes = EXCLUDED.attributes, updated_at = NOW();
