INSERT INTO models (model_id, brand_id, model_name, model_types, creator, years_active, links, description, recording_notes, artist_reference, attributes) VALUES ('8a49c207-7e5c-4130-85b7-f07472fb1d52', 'cb6ef06a-1e2c-11f1-a0d3-0072ee78ad39', 'Russian Big Muff Pi', '{Harmonic Coloration,Stomp,Dynamics}'::model_type[], NULL, NULL, 'Big Muff PI (Russian)', 'Fuzz / Distortion / Sustainer', 'Thick and brutal. A pinch smoother than its American-made comrade, the Russian Muff exhibits slightly less sustain, yet retains that unmistakable Big Muff sound. Prized by bass players for its edge, and sought after by guitarists seeking its unique flavor. A heavier, thicker Muff with more low end, rougher texture, and less top-end fizz. Grindy, aggressive, and weighty, with massive lows and a raw, woolly character.', NULL, NULL::jsonb) ON CONFLICT (model_id) DO UPDATE SET model_types = EXCLUDED.model_types, creator = EXCLUDED.creator, years_active = EXCLUDED.years_active, description = EXCLUDED.description, recording_notes = EXCLUDED.recording_notes, artist_reference = EXCLUDED.artist_reference, attributes = EXCLUDED.attributes, updated_at = NOW();
