INSERT INTO models (model_id, brand_id, model_name, model_types, creator, years_active, links, description, recording_notes, artist_reference, attributes) VALUES ('458f8b5d-2624-4e2e-bdc5-c3e72b5e6f0f', 'cb708484-1e2c-11f1-a0d3-0072ee78ad39', 'The Guv''nor', '{Harmonic Coloration,Stomp}'::model_type[], NULL, '1988', 'Guv''nor (Reissue)', 'analog distortion/overdrive pedal , featuring a 3-band EQ (Bass, Middle, Treble), Gain, and Volume controls..', 'designed to emulate the Marshall JCM800 amp sound. It is designed for high-gain, British-style distortion. Aggressive, compressed Marshall grind with a tight low end and biting upper mids.', NULL, NULL::jsonb) ON CONFLICT (model_id) DO UPDATE SET model_types = EXCLUDED.model_types, creator = EXCLUDED.creator, years_active = EXCLUDED.years_active, description = EXCLUDED.description, recording_notes = EXCLUDED.recording_notes, artist_reference = EXCLUDED.artist_reference, attributes = EXCLUDED.attributes, updated_at = NOW();
INSERT INTO models (model_id, brand_id, model_name, model_types, creator, years_active, links, description, recording_notes, artist_reference, attributes) VALUES ('f924c123-c339-455e-9b51-89e3e66f2acd', 'e4fe0c9a-1e3c-11f1-a0d3-0072ee78ad39', 'The Ladder', '{EQ,Modulation}'::model_type[], 'Robert Moog', '1966', 'Mood The Ladder', 'iconic, patented transistor-based voltage-controlled filter (VCF) renowned for its 24dB/octave slope and warm, "creamy" sound. It was the first voltage-controlled filter in synthesizers, famously used in the Minimoog to create rich, saturated, and "fat" analog bass and lead tones.', NULL, NULL, NULL::jsonb) ON CONFLICT (model_id) DO UPDATE SET model_types = EXCLUDED.model_types, creator = EXCLUDED.creator, years_active = EXCLUDED.years_active, description = EXCLUDED.description, recording_notes = EXCLUDED.recording_notes, artist_reference = EXCLUDED.artist_reference, attributes = EXCLUDED.attributes, updated_at = NOW();
