INSERT INTO models (model_id, brand_id, model_name, model_types, creator, years_active, links, description, recording_notes, artist_reference, attributes) VALUES ('2cc0bdbc-a0a3-4d40-b1f2-9ddbf893052e', '288aa0ec-aa11-4b27-93f1-5a91b588437f', 'TS808 (Tube Screamer)', '{Harmonic Coloration,Stomp}'::model_type[], NULL, '1979', 'Ibanez Tube Screamer', 'The original Tube Screamer circuit with slightly lower output and smoother clipping, designed to gently push an amp rather than dominate it', 'Smooth and polite. Warm, soft, mid-forward drive with rounded highs that blends into the amp and feels forgiving under the fingers.', NULL, NULL::jsonb) ON CONFLICT (model_id) DO UPDATE SET model_types = EXCLUDED.model_types, creator = EXCLUDED.creator, years_active = EXCLUDED.years_active, description = EXCLUDED.description, recording_notes = EXCLUDED.recording_notes, artist_reference = EXCLUDED.artist_reference, attributes = EXCLUDED.attributes, updated_at = NOW();
INSERT INTO models (model_id, brand_id, model_name, model_types, creator, years_active, links, description, recording_notes, artist_reference, attributes) VALUES ('e56d35d3-1ff2-4b15-bab3-fc07e03fd93f', '288aa0ec-aa11-4b27-93f1-5a91b588437f', 'TS808DX', '{Harmonic Coloration,Stomp}'::model_type[], NULL, NULL, NULL, '"Tube Screamer Overdrive Pro Deluxe" combined the classic TS808 overdrive circuit w/ an independent high gain (+20dB or more) in a single unit.', NULL, NULL, NULL::jsonb) ON CONFLICT (model_id) DO UPDATE SET model_types = EXCLUDED.model_types, creator = EXCLUDED.creator, years_active = EXCLUDED.years_active, description = EXCLUDED.description, recording_notes = EXCLUDED.recording_notes, artist_reference = EXCLUDED.artist_reference, attributes = EXCLUDED.attributes, updated_at = NOW();
INSERT INTO models (model_id, brand_id, model_name, model_types, creator, years_active, links, description, recording_notes, artist_reference, attributes) VALUES ('9fcb82cf-f9e3-4172-984e-08449118e3b5', '288aa0ec-aa11-4b27-93f1-5a91b588437f', 'TS9 (Tube Screamer)', '{Harmonic Coloration,Stomp}'::model_type[], NULL, NULL, 'TS9 Tube Screamer', 'A hotter, more aggressive revision of the Tube Screamer with increased output and a slightly harder clipping character.', 'Louder and sharper. Brighter and punchier with more bite in the upper mids, cutting through mixes more assertively.', NULL, NULL::jsonb) ON CONFLICT (model_id) DO UPDATE SET model_types = EXCLUDED.model_types, creator = EXCLUDED.creator, years_active = EXCLUDED.years_active, description = EXCLUDED.description, recording_notes = EXCLUDED.recording_notes, artist_reference = EXCLUDED.artist_reference, attributes = EXCLUDED.attributes, updated_at = NOW();
