INSERT INTO models (model_id, brand_id, model_name, model_types, creator, years_active, links, description, recording_notes, artist_reference, attributes) VALUES ('6ce92e74-2017-11f1-a0d3-0072ee78ad39', 'cb6a7a6c-1e2c-11f1-a0d3-0072ee78ad39', 'Tube Driver', '{Harmonic Coloration,Stomp}'::model_type[], 'Brent Butler', '1978-', 'B.K. Butler Tube Driver', '(Same as Chandler Tube Driver, but no longer marketed as Chandler) a legendary, high-voltage overdrive pedal featuring a 12AX7 vacuum tube', 'warm, compressed, and rich tones', 'Eric Johnson, David GIlmour, Billy Gibbons, Joe Satriani', NULL::jsonb) ON CONFLICT (model_id) DO UPDATE SET model_types = EXCLUDED.model_types, creator = EXCLUDED.creator, years_active = EXCLUDED.years_active, description = EXCLUDED.description, recording_notes = EXCLUDED.recording_notes, artist_reference = EXCLUDED.artist_reference, attributes = EXCLUDED.attributes, updated_at = NOW();
INSERT INTO models (model_id, brand_id, model_name, model_types, creator, years_active, links, description, recording_notes, artist_reference, attributes) VALUES ('6ce92e74-2017-11f1-a0d3-0072ee78ad39', 'cb6a7a6c-1e2c-11f1-a0d3-0072ee78ad39', 'Tube Driver', '{Harmonic Coloration,Stomp}'::model_type[], 'Brent Butler', '1987-89', NULL, 'a legendary, high-voltage overdrive pedal featuring a 12AX7 vacuum tube. 3-knob design. Lower quality. [NOTE: I''ve kept this entry for differentiation. All of the models I''m using are B.K.]', 'warm, compressed, and rich tones. Considered more "raw" and vintage', NULL, NULL::jsonb) ON CONFLICT (model_id) DO UPDATE SET model_types = EXCLUDED.model_types, creator = EXCLUDED.creator, years_active = EXCLUDED.years_active, description = EXCLUDED.description, recording_notes = EXCLUDED.recording_notes, artist_reference = EXCLUDED.artist_reference, attributes = EXCLUDED.attributes, updated_at = NOW();
