INSERT INTO models (model_id, brand_id, model_name, model_types, creator, years_active, links, description, recording_notes, artist_reference, attributes) VALUES ('63ea55bf-308b-43ff-8301-706fa026b33e', 'e50495ba-1e3c-11f1-a0d3-0072ee78ad39', 'Twin Twelve 1484', NULL::model_type[], NULL, NULL, NULL, '60-watt, 2x12 tube guitar amplifier produced by Danelectro for Sears between 1963 and 1967. Known for its gray "wallpaper" finish, this iconic, affordable 1960s amp features 6L6 power tubes, a 2x12 cabinet built-in tremolo/reverb, and a unique, mid-forward tone favored by artists like Jack White Default Driver: Jensen C12Q (or Fisher 12-4L)', NULL, NULL, NULL::jsonb) ON CONFLICT (model_id) DO UPDATE SET model_types = EXCLUDED.model_types, creator = EXCLUDED.creator, years_active = EXCLUDED.years_active, description = EXCLUDED.description, recording_notes = EXCLUDED.recording_notes, artist_reference = EXCLUDED.artist_reference, attributes = EXCLUDED.attributes, updated_at = NOW();
INSERT INTO models (model_id, brand_id, model_name, model_types, creator, years_active, links, description, recording_notes, artist_reference, attributes) VALUES ('395934cf-3739-4e94-b15e-067bf7096db4', 'f7733c38-1e3c-11f1-a0d3-0072ee78ad39', 'Twinkleland 2x12', NULL::model_type[], 'Peter Van Weelden', NULL, 'Van Weelden Twinkleland', '2x12 cabinet designed for use w/ Van Weelden Twinkleland heads (custom and hand built in Netherlands) Default Drivers: Electro-Voice EVM12L', NULL, NULL, NULL::jsonb) ON CONFLICT (model_id) DO UPDATE SET model_types = EXCLUDED.model_types, creator = EXCLUDED.creator, years_active = EXCLUDED.years_active, description = EXCLUDED.description, recording_notes = EXCLUDED.recording_notes, artist_reference = EXCLUDED.artist_reference, attributes = EXCLUDED.attributes, updated_at = NOW();
INSERT INTO models (model_id, brand_id, model_name, model_types, creator, years_active, links, description, recording_notes, artist_reference, attributes) VALUES ('a23cdbdd-46e7-46ff-8f06-fc6447beccc7', '1ebff14d-6b8f-4d2f-a934-92283151e281', 'Twintone', NULL::model_type[], NULL, '80s-90s', 'Twintone III Combo', 'It features 100 editable program RAM locations, 20 distinct effect chains (using up to 6 simultaneous effects), and 41 effect types, including modulation, delay, reverb, and unique, high-quality, "glassy" modulation effects. Includes distortion, overdrive, compression, exciter, chorus, phaser, flanger, pitch shifters, and various delays/reverbs.', 'Known for its distinct 80s/90s, high-quality, and "glassy" digital effects, often used in studio recordings and live performances.', NULL, NULL::jsonb) ON CONFLICT (model_id) DO UPDATE SET model_types = EXCLUDED.model_types, creator = EXCLUDED.creator, years_active = EXCLUDED.years_active, description = EXCLUDED.description, recording_notes = EXCLUDED.recording_notes, artist_reference = EXCLUDED.artist_reference, attributes = EXCLUDED.attributes, updated_at = NOW();
