INSERT INTO models (model_id, brand_id, model_name, model_types, creator, years_active, links, description, recording_notes, artist_reference, attributes) VALUES ('880c2ec0-2019-11f1-a0d3-0072ee78ad39', 'f7719248-1e3c-11f1-a0d3-0072ee78ad39', 'U47', '{Microphone}'::model_type[], NULL, NULL, 'U47', 'The first microphone with electrical pattern switching (cardioid/omni); multi-pattern large tube condenser circuit w/ output transformer.  K47 capsule, VF14 tube', 'legendary tube mic, warmth, richness in vocals and orchestral. full range, sparkling highs. One of the most recognizable mics in recording,  prized for its amazing realism and clarity.', 'Andrea Bocelli, Radiohead ("Hail to the Thief") , Frank Zappa, Ray Charles, Ella Fitzgerald, Beck ("Sea Change"), Paul McCartney, Anita Baker', NULL::jsonb) ON CONFLICT (model_id) DO UPDATE SET model_types = EXCLUDED.model_types, creator = EXCLUDED.creator, years_active = EXCLUDED.years_active, description = EXCLUDED.description, recording_notes = EXCLUDED.recording_notes, artist_reference = EXCLUDED.artist_reference, attributes = EXCLUDED.attributes, updated_at = NOW();
