INSERT INTO models (model_id, brand_id, model_name, model_types, creator, years_active, links, description, recording_notes, artist_reference, attributes) VALUES ('384e8b9c-85b8-457f-8098-ac2916e3b8c7', 'cb683482-1e2c-11f1-a0d3-0072ee78ad39', 'Uberkab', NULL::model_type[], NULL, NULL, NULL, '4x12" straight, closed-back speaker cabinet designed for high-gain,, notably the Uberschall and Twin Jet heads. It features a 210-watt RMS power handling, 16-ohm impedance, and a unique "X-pattern" load of two Celestion Vintage 30s and two Celestion G12T-75s (by default) NOTE: If Speakers aren''t specified in the effect, then this is the default setup.', NULL, NULL, NULL::jsonb) ON CONFLICT (model_id) DO UPDATE SET model_types = EXCLUDED.model_types, creator = EXCLUDED.creator, years_active = EXCLUDED.years_active, description = EXCLUDED.description, recording_notes = EXCLUDED.recording_notes, artist_reference = EXCLUDED.artist_reference, attributes = EXCLUDED.attributes, updated_at = NOW();
INSERT INTO models (model_id, brand_id, model_name, model_types, creator, years_active, links, description, recording_notes, artist_reference, attributes) VALUES ('d66254df-de0d-4807-bd92-3135cb9212d4', 'cb683482-1e2c-11f1-a0d3-0072ee78ad39', 'Uberschall', NULL::model_type[], NULL, NULL, 'Bogner Amps', '(100-150W) 2ch (clean/crunch and ultra hihg-gain)  high-gain amp w/ 6 x 12AX7 preamp tubes. 150W uses 4 x KT88 tubes, others use 4 x EL34s.', 'designed for heavy metal', NULL, NULL::jsonb) ON CONFLICT (model_id) DO UPDATE SET model_types = EXCLUDED.model_types, creator = EXCLUDED.creator, years_active = EXCLUDED.years_active, description = EXCLUDED.description, recording_notes = EXCLUDED.recording_notes, artist_reference = EXCLUDED.artist_reference, attributes = EXCLUDED.attributes, updated_at = NOW();
INSERT INTO models (model_id, brand_id, model_name, model_types, creator, years_active, links, description, recording_notes, artist_reference, attributes) VALUES ('79d6be31-bcbb-49f1-9308-ef12548ab1ae', '07247908-734d-4379-b2ad-82d548c475d3', 'UL3 112', NULL::model_type[], NULL, NULL, 'Ultralight UL3 Series', NULL, NULL, NULL, NULL::jsonb) ON CONFLICT (model_id) DO UPDATE SET model_types = EXCLUDED.model_types, creator = EXCLUDED.creator, years_active = EXCLUDED.years_active, description = EXCLUDED.description, recording_notes = EXCLUDED.recording_notes, artist_reference = EXCLUDED.artist_reference, attributes = EXCLUDED.attributes, updated_at = NOW();
INSERT INTO models (model_id, brand_id, model_name, model_types, creator, years_active, links, description, recording_notes, artist_reference, attributes) VALUES ('dfaed27d-c2b5-4972-a0fd-95bd9471ce43', '147af267-3b4d-43c8-a091-a66c906304dc', 'Ultimate Octave', '{Harmonic Coloration,Stomp}'::model_type[], NULL, NULL, 'Ultimate Octave', 'a smooth BC108 transistor fuzz with an active tone circuit, plus a second footswitch to kick in a searing Octave Up on command. The Fat/Bright switch changes the entire contour, affecting both the fuzz and the octave, so you can choose either the thicker, mid forward Fat setting or the more open Bright setting with defined highs and a slightly scooped mid-range. It isn’t fussy about guitar choice either—tracking is solid on any pickup most anywhere on the neck, though the neck pickup will give you the most pronounced octave clarity. If you need more octave, turn Tone up, back Distortion down a touch, and raise Volume. Simple', NULL, 'Joe Satriani', NULL::jsonb) ON CONFLICT (model_id) DO UPDATE SET model_types = EXCLUDED.model_types, creator = EXCLUDED.creator, years_active = EXCLUDED.years_active, description = EXCLUDED.description, recording_notes = EXCLUDED.recording_notes, artist_reference = EXCLUDED.artist_reference, attributes = EXCLUDED.attributes, updated_at = NOW();
