INSERT INTO models (model_id, brand_id, model_name, model_types, creator, years_active, links, description, recording_notes, artist_reference, attributes) VALUES ('22f8747a-322a-48e0-8e04-7052c742e1f6', 'cb6ae22c-1e2c-11f1-a0d3-0072ee78ad39', 'Wah Wah', '{Modulation,Stomp}'::model_type[], NULL, NULL, NULL, 'Wah', 'known for its wide, vocal-like sweep, pronounced midrange, and inductorless circuit design. These vintage-style pedals, often featuring a steel, hammertone-finished enclosure, offer a raw, throaty growl popular in rock and funk', NULL, NULL::jsonb) ON CONFLICT (model_id) DO UPDATE SET model_types = EXCLUDED.model_types, creator = EXCLUDED.creator, years_active = EXCLUDED.years_active, description = EXCLUDED.description, recording_notes = EXCLUDED.recording_notes, artist_reference = EXCLUDED.artist_reference, attributes = EXCLUDED.attributes, updated_at = NOW();
