INSERT INTO models (model_id, brand_id, model_name, model_types, creator, years_active, links, description, recording_notes, artist_reference, attributes) VALUES ('c8466df9-e04a-46d4-a87d-97c880acb6f9', 'cb6b54f0-1e2c-11f1-a0d3-0072ee78ad39', 'Wah/Anti-Wah', '{Modulation,Stomp}'::model_type[], NULL, NULL, NULL, 'voltage-controlled filter circuit that uses two identical bandpass filters', 'Unlike the classic Cry Baby or Vox wahs, which have a specific "throaty" growl caused by their inductor-based design, the Anderton circuit was cleaner and more transparent. It provided a wider frequency sweep and reached unity gain, avoiding the volume drop common in many vintage pedals.', NULL, NULL::jsonb) ON CONFLICT (model_id) DO UPDATE SET model_types = EXCLUDED.model_types, creator = EXCLUDED.creator, years_active = EXCLUDED.years_active, description = EXCLUDED.description, recording_notes = EXCLUDED.recording_notes, artist_reference = EXCLUDED.artist_reference, attributes = EXCLUDED.attributes, updated_at = NOW();
