INSERT INTO models (model_id, brand_id, model_name, model_types, creator, years_active, links, description, recording_notes, artist_reference, attributes) VALUES ('b5979244-1944-4cf3-a530-51f7257e3a0c', '288aa0ec-aa11-4b27-93f1-5a91b588437f', 'WH10', '{Modulation,Stomp}'::model_type[], NULL, NULL, 'Ibanez WH10v3 (Reissue)', 'highly popular wah pedal . The guitar/bass range switch enables switching between two preset frequency ranges best suited for each instrument. This is also the first wah pedal to utilize a multiple feedback opamp circuit, creating a much different tonal quality versus more common inductor based wahs', NULL, NULL, NULL::jsonb) ON CONFLICT (model_id) DO UPDATE SET model_types = EXCLUDED.model_types, creator = EXCLUDED.creator, years_active = EXCLUDED.years_active, description = EXCLUDED.description, recording_notes = EXCLUDED.recording_notes, artist_reference = EXCLUDED.artist_reference, attributes = EXCLUDED.attributes, updated_at = NOW();
