INSERT INTO models (model_id, brand_id, model_name, model_types, creator, years_active, links, description, recording_notes, artist_reference, attributes) VALUES ('e73d0594-f11b-4837-ae6b-0b0f38d59324', 'cb6ec036-1e2c-11f1-a0d3-0072ee78ad39', 'WT800', NULL::model_type[], 'David Nordschow', 'Mid–1990s', NULL, 'WT = "World Tour". Renowned powerful hybrid bass amp. 880W (stereo / bridged) 440W per side · solid-state power · tube preamp (12AX7) · dual power amps · Bass / Mid / Treble 5-band EQ + semi-parametric mids · Enhance control · compressor · DI', 'Clean, hi-fi, extremely articulate; fast transient response with tight low end; famous for slap and modern rock bass; widely associated with Marcus Miller, Victor Wooten, and 90s–2000s studio bass tone. Modern, dynamic, rock solid bass sound (R&B, hip hop, metal, jazz)', NULL, NULL::jsonb) ON CONFLICT (model_id) DO UPDATE SET model_types = EXCLUDED.model_types, creator = EXCLUDED.creator, years_active = EXCLUDED.years_active, description = EXCLUDED.description, recording_notes = EXCLUDED.recording_notes, artist_reference = EXCLUDED.artist_reference, attributes = EXCLUDED.attributes, updated_at = NOW();
